// CONFIGURATION
const daysLookback = 7;
const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - daysLookback);

// Get data from previous node
const rows = $input.all();

// Filter and format for LLM context
let chatHistory = "";
let count = 0;

for (const row of rows) {
  const item = row.json;

  // Parse date from your specific format (yyyy-MM-dd HH:mm:ss)
  const rowDate = new Date(item['Date']);

  // Filter by date range
  if (rowDate >= oneWeekAgo) {
    count++;
    // Construct readable block for AI analysis
    chatHistory += `[${item['Date']}] Category: ${item['Sentiment']}
User: ${item['User Query']}
Bot: ${item['Bot Response']}
---
`;
  }
}

// Return prepared payload
return {
  json: {
    reportData: chatHistory,
    totalConversations: count,
    dateStart: oneWeekAgo.toISOString().split('T')[0],
    dateEnd: new Date().toISOString().split('T')[0]
  }
};
